package com.ultras.bans;
import com.ultras.bans.config.ConfigManager; import com.ultras.bans.database.Database; import com.ultras.bans.discord.DiscordService; import com.ultras.bans.security.SecurityService; import com.ultras.bans.service.*; import com.ultras.bans.command.AdminCommand; import com.ultras.bans.gui.GUIListener; import com.ultras.bans.gui.GUIService; import com.ultras.bans.listener.PlayerListener; import org.bukkit.Bukkit; import org.bukkit.command.*; import org.bukkit.plugin.java.JavaPlugin; import java.util.*;
public final class ULTRASBansPlugin extends JavaPlugin {
 private ConfigManager configs; private Database database; private PlayerService players; private PunishmentService punishments; private FreezeService freeze; private JailService jail; private JailInventoryService jailInventory; private SecurityService security; private DiscordService discord; private GUIService gui; private com.ultras.bans.service.VanishService vanish; private NetworkEnforcer network; private NetworkMessageSender networkSender;
 @Override public void onEnable(){saveDefaultConfig();getServer().getMessenger().registerOutgoingPluginChannel(this, NetworkChannel.CHANNEL);getServer().getMessenger().registerIncomingPluginChannel(this, NetworkChannel.CHANNEL, new com.ultras.bans.service.NetworkMessageListener(this));configs=new ConfigManager(this);configs.load();database=new Database(this);try{database.init();}catch(Exception e){getLogger().severe("Database initialization failed: "+e.getMessage());getServer().getPluginManager().disablePlugin(this);return;}players=new PlayerService(this,database);punishments=new PunishmentService(this,database);freeze=new FreezeService(this);jail=new JailService(this);jailInventory=new JailInventoryService(this);jail.load();security=new SecurityService(this);discord=new DiscordService(this);gui=new GUIService(this);vanish=new com.ultras.bans.service.VanishService(this);network=new NetworkEnforcer(this);networkSender=new NetworkMessageSender(this);AdminCommand cmd=new AdminCommand(this);String[] names={"ban","unban","kick","ipban","ip_ban","unipban","mute","unmute","warn","freeze","frz","jail","unjail","setjail","vn","nv","admin","tam","game0","game1","game2","game3","games","tp","tphere","ip_list","ultrasbans","ub"};for(String n:names){PluginCommand c=getCommand(n);if(c!=null){c.setExecutor(cmd);c.setTabCompleter(cmd);}}getServer().getPluginManager().registerEvents(new PlayerListener(this),this);getServer().getPluginManager().registerEvents(new com.ultras.bans.listener.ChatListener(this),this);getServer().getPluginManager().registerEvents(new GUIListener(this),this);Bukkit.getScheduler().runTaskTimerAsynchronously(this,()->database.expireDue(),100L,20L*getConfig().getInt("expiry-check-seconds",5));Bukkit.getScheduler().runTaskTimer(this,()->network.tick(),100L,100L);getLogger().info("ULTRAS_bans_v1 enabled successfully.");}
 @Override public void onDisable(){if(discord!=null)discord.shutdown();if(database!=null)database.close();}
 public ConfigManager configs(){return configs;} public Database database(){return database;} public PlayerService players(){return players;} public PunishmentService punishments(){return punishments;} public FreezeService freeze(){return freeze;} public JailService jail(){return jail;} public JailInventoryService jailInventory(){return jailInventory;} public SecurityService security(){return security;} public DiscordService discord(){return discord;} public GUIService gui(){return gui;} public com.ultras.bans.service.VanishService vanish(){return vanish;} public NetworkMessageSender networkSender(){return networkSender;} public String serverId(){return configs.get("proxy.yml").getString("server-id","server-1");}
 public void reloadAll(){reloadConfig();configs.reload();jail.load();}
}
